1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>Thread + Register Layout</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  /* Thread-local view (lane × reg table) */
10	  .tview { margin-top:10px; }
11	  .tview table { border-collapse:collapse; width:100%; font-size:11px; }
12	  .tview th, .tview td { border:1px solid var(--border); padding:3px 6px; text-align:center; }
13	  .tview th { background:var(--bg); font-weight:600; color:var(--dim); font-size:10px; }
14	  .tview td { font-weight:700; font-family:'SF Mono','Fira Code',monospace; }
15	  .tview td.hov-lane { background:#dbeafe; color:#1e40af; }
16	</style>
17	</head>
18	<body>
19	
20	<h1>Layout: S[(8, 4, 2) : (4@laneid, 1@laneid, 1@reg)]</h1>
21	<div class="sub">click cell to see assignment</div>
22	
23	<div class="panels" id="panels">
24	  <div class="panel">
25	    <h2>Logical 8×8 Matrix</h2>
26	    <div class="nota"></div>
27	    <div class="grid" id="g0"></div>
28	  </div>
29	  <div class="panel">
30	    <h2>Thread Assignment</h2>
31	    <div class="nota"></div>
32	    <div class="grid" id="g1"></div>
33	    <div class="tview" id="tv"></div>
34	  </div>
35	  <svg class="arrow-svg" id="arrow"></svg>
36	</div>
37	
38	<div class="formula-bar" id="fb"></div>
39	<div class="leg" id="lg"></div>
40	
41	<script>
42	const N = 8;
43	
44	// 32 laneid colors — same palette as swizzle bank colors
45	const BK8 = ['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
46	const LANE_COLORS = [];
47	for (let v = 0; v < 4; v++) {
48	  for (let h = 0; h < 8; h++) {
49	    const base = BK8[h];
50	    const r = parseInt(base.slice(1,3),16), g = parseInt(base.slice(3,5),16), b = parseInt(base.slice(5,7),16);
51	    const shift = [-20, 0, 20, 40][v];
52	    const clamp = x => Math.max(0, Math.min(255, x + shift));
53	    LANE_COLORS.push(`rgb(${clamp(r)},${clamp(g)},${clamp(b)})`);
54	  }
55	}
56	function laneColor(lid) { return LANE_COLORS[lid % 32]; }
57	function laneTextColor(lid) { return lid < 8 ? '#fff' : '#222'; }
58	
59	// TileLayout(S[(8, 4, 2) : (4@laneid, 1@laneid, 1@reg)])
60	function threadLane(r, c) { return r * 4 + Math.floor(c / 2); }
61	function threadReg(r, c) { return c % 2; }
62	
63	function mk(t, c) { const d = document.createElement(t); if (c) d.className = c; return d; }
64	
65	let hovCell = null;
66	let drawing = false;
67	
68	function draw() {
69	  drawing = true;
70	  drawLogicalGrid();
71	  drawThreadGrid();
72	  drawThreadView();
73	  drawFormula();
74	  drawArrow();
75	  drawLegend();
76	  setTimeout(() => { drawing = false; }, 0);
77	}
78	
79	function drawLogicalGrid() {
80	  const g = document.getElementById('g0');
81	  g.innerHTML = '';
82	  g.style.gridTemplateColumns = '24px repeat(' + N + ',1fr)';
83	
84	  g.appendChild(mk('div', 'hdr'));
85	  for (let c = 0; c < N; c++) {
86	    const h = mk('div', 'hdr'); h.textContent = 'c' + c; g.appendChild(h);
87	  }
88	
89	  for (let r = 0; r < N; r++) {
90	    const rl = mk('div', 'rl'); rl.textContent = 'r' + r; g.appendChild(rl);
91	    for (let c = 0; c < N; c++) {
92	      const d = mk('div', 'cell');
93	      d.dataset.r = r;
94	      d.dataset.c = c;
95	      d.textContent = r * N + c;
96	      d.style.background = '#e8eaed';
97	      d.style.color = '#333';
98	      if (hovCell && r === hovCell.r && c === hovCell.c) d.classList.add('hov');
99	      g.appendChild(d);
100	    }
101	  }
102	}
103	
104	function drawThreadGrid() {
105	  const g = document.getElementById('g1');
106	  g.innerHTML = '';
107	  g.style.gridTemplateColumns = '24px repeat(' + N + ',1fr)';
108	
109	  g.appendChild(mk('div', 'hdr'));
110	  for (let c = 0; c < N; c++) {
111	    const h = mk('div', 'hdr'); h.textContent = 'c' + c; g.appendChild(h);
112	  }
113	
114	  for (let r = 0; r < N; r++) {
115	    const rl = mk('div', 'rl'); rl.textContent = 'r' + r; g.appendChild(rl);
116	    for (let c = 0; c < N; c++) {
117	      const lid = threadLane(r, c);
118	      const d = mk('div', 'cell');
119	      d.dataset.r = r;
120	      d.dataset.c = c;
121	      d.style.background = laneColor(lid);
122	      d.style.color = laneTextColor(lid);
123	      d.textContent = r * N + c;
124	      if (hovCell && r === hovCell.r && c === hovCell.c) d.classList.add('hov');
125	      g.appendChild(d);
126	    }
127	  }
128	}
129	
130	function drawThreadView() {
131	  const tv = document.getElementById('tv');
132	  if (!hovCell) {
133	    tv.innerHTML = '';
134	    return;
135	  }
136	  const {r, c} = hovCell;
137	  const lid = threadLane(r, c);
138	
139	  // Show the two elements this lane holds
140	  let html = '<table><tr><th></th><th>reg 0</th><th>reg 1</th></tr>';
141	  html += `<tr><th>lane ${lid}</th>`;
142	  for (let reg = 0; reg < 2; reg++) {
143	    // Find the (r,c) for this lane and reg
144	    const cr = r; // same row for both regs of this lane
145	    const cc = Math.floor(c / 2) * 2 + reg;
146	    const val = cr * N + cc;
147	    const isHov = cr === hovCell.r && cc === hovCell.c;
148	    html += `<td class="${isHov ? 'hov-lane' : ''}" style="background:${laneColor(lid)}; color:${laneTextColor(lid)}; opacity:${isHov ? 1 : 0.6}">${val}</td>`;
149	  }
150	  html += '</tr></table>';
151	  tv.innerHTML = html;
152	}
153	
154	function drawFormula() {
155	  const fb = document.getElementById('fb');
156	  if (!hovCell) {
157	    fb.innerHTML = '<div class="ftitle">Click a cell to see thread (laneid) and register assignment</div>';
158	    return;
159	  }
160	  const {r, c} = hovCell;
161	  const logVal = r * N + c;
162	  const lid = threadLane(r, c), reg = threadReg(r, c);
163	  let html = `<div class="ftitle">Element ${logVal} at (row=${r}, col=${c})</div>`;
164	  html += '<div class="fcontent">';
165	  html += `addr = row × 4@laneid + (col // 2) × 1@laneid + (col % 2) × 1@reg<br>`;
166	  html += `&nbsp;&nbsp;&nbsp;&nbsp; = ${r} × 4@laneid + (${c} // 2) × 1@laneid + (${c} % 2) × 1@reg<br>`;
167	  html += `&nbsp;&nbsp;&nbsp;&nbsp; = <b>${lid}</b>@laneid + <b>${reg}</b>@reg`;
168	  html += '</div>';
169	  fb.innerHTML = html;
170	}
171	
172	// Arrow overlay
173	const panels = document.getElementById('panels');
174	const arrowSvg = document.getElementById('arrow');
175	
176	function drawArrow() {
177	  arrowSvg.innerHTML = '';
178	  const hovs = panels.querySelectorAll('.cell.hov');
179	  if (hovs.length < 2) return;
180	  const pr = panels.getBoundingClientRect();
181	  const a = hovs[0].getBoundingClientRect(), b = hovs[1].getBoundingClientRect();
182	  const x1 = a.left + a.width/2 - pr.left, y1 = a.top - pr.top;
183	  const x2 = b.left + b.width/2 - pr.left, y2 = b.top - pr.top;
184	  const mx = (x1 + x2) / 2, my = -10;
185	  const d = `M${x1},${y1} Q${mx},${my} ${x2},${y2}`;
186	  const ns = 'http://www.w3.org/2000/svg';
187	  const defs = document.createElementNS(ns, 'defs');
188	  const marker = document.createElementNS(ns, 'marker');
189	  marker.setAttribute('id', 'ah'); marker.setAttribute('markerWidth', '8'); marker.setAttribute('markerHeight', '6');
190	  marker.setAttribute('refX', '7'); marker.setAttribute('refY', '3'); marker.setAttribute('orient', 'auto');
191	  const poly = document.createElementNS(ns, 'polygon');
192	  poly.setAttribute('points', '0 0, 8 3, 0 6'); poly.setAttribute('fill', '#222');
193	  marker.appendChild(poly); defs.appendChild(marker); arrowSvg.appendChild(defs);
194	  const path = document.createElementNS(ns, 'path');
195	  path.setAttribute('d', d); path.setAttribute('marker-end', 'url(#ah)');
196	  arrowSvg.appendChild(path);
197	}
198	
199	function clearHov() {
200	  panels.querySelectorAll('.cell.hov').forEach(d => d.classList.remove('hov'));
201	  arrowSvg.innerHTML = '';
202	  hovCell = null;
203	}
204	
205	panels.addEventListener('click', e => {
206	  const cell = e.target.closest('.cell');
207	  if (!cell || cell.dataset.r === undefined) return;
208	  const r = +cell.dataset.r, c = +cell.dataset.c;
209	  if (hovCell && hovCell.r === r && hovCell.c === c) {
210	    clearHov();
211	    draw();
212	    return;
213	  }
214	  clearHov();
215	  hovCell = { r, c };
216	  draw();
217	});
218	
219	// Legend
220	function drawLegend() {
221	  const lg = document.getElementById('lg');
222	  lg.innerHTML = '';
223	  const r1 = mk('div', 'leg-row');
224	  r1.style.gap = '3px';
225	  for (let l = 0; l < 32; l++) {
226	    const pair = mk('div', 'li');
227	    pair.style.gap = '1px';
228	    for (let reg = 0; reg < 2; reg++) {
229	      const sw = mk('div', 'swtch');
230	      sw.style.background = laneColor(l);
231	      sw.style.display = 'inline-flex'; sw.style.alignItems = 'center'; sw.style.justifyContent = 'center';
232	      sw.style.fontSize = '7px'; sw.style.fontWeight = '700';
233	      sw.style.color = laneTextColor(l);
234	      sw.textContent = l;
235	      pair.appendChild(sw);
236	    }
237	    r1.appendChild(pair);
238	  }
239	  lg.appendChild(r1);
240	  const r2 = mk('div', 'leg-row');
241	  const ann = mk('div', 'li');
242	  ann.style.fontSize = '11px';
243	  ann.textContent = 'Each color pair = 1 thread (reg 0, reg 1)  |  laneid = threadIdx.x % 32';
244	  r2.appendChild(ann);
245	  lg.appendChild(r2);
246	}
247	
248	draw();
249	</script>
250	</body>
251	</html>
