1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>Tiled Layout</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  .cell.tile-hi { background:#dbeafe !important; color:#1e40af !important; }
10	
11	  /* Memory strip */
12	  .mlab { font-size:11px; color:var(--dim); text-align:center; margin-top:14px; margin-bottom:3px; font-weight:600; }
13	  .mstrip { display:grid; grid-template-columns:repeat(32,1fr); gap:1px; }
14	  .ms {
15	    height:24px; border-radius:3px; display:flex; align-items:center; justify-content:center;
16	    font-size:7px; font-weight:700; transition:all .18s; min-width:0; background:#e2e5ea; color:var(--dim);
17	  }
18	  .ms.hov-hit { border:2px solid var(--accent); z-index:2; box-shadow:0 0 4px rgba(59,130,246,.4); background:#d0e0f0; color:#222; font-size:8px; }
19	</style>
20	</head>
21	<body>
22	
23	<h1>S[(4, 2, 2, 4) : (16, 4, 8, 1)]</h1>
24	<div class="sub">Logical view vs Physical memory &nbsp;|&nbsp; click cell to see mapping</div>
25	
26	<div class="panels" id="panels">
27	  <div class="panel">
28	    <h2>Logical Matrix</h2>
29	    <div class="nota" id="n0"></div>
30	    <div class="grid" id="g0"></div>
31	    <div class="mlab" id="ml0"></div>
32	    <div class="mstrip" id="m0"></div>
33	  </div>
34	  <div class="panel">
35	    <h2>Physical Memory (tiled 2×4)</h2>
36	    <div class="nota" id="n1"></div>
37	    <div class="grid" id="g1"></div>
38	    <div class="mlab" id="ml1"></div>
39	    <div class="mstrip" id="m1"></div>
40	  </div>
41	  <svg class="arrow-svg" id="arrow"></svg>
42	</div>
43	
44	<div class="formula-bar" id="fb"></div>
45	
46	<script>
47	const N = 8, TOTAL = N * N;
48	const TILE_R = 2, TILE_C = 4;
49	const TILE_SZ = TILE_R * TILE_C;
50	const N_TILE_R = N / TILE_R;
51	const N_TILE_C = N / TILE_C;
52	
53	const TILE_8 = ['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
54	function tileId(r, c) {
55	  return Math.floor(r / TILE_R) * N_TILE_C + Math.floor(c / TILE_C);
56	}
57	
58	function addrFlat(r, c) { return r * N + c; }
59	
60	function addrTiled(r, c) {
61	  const ro = Math.floor(r / TILE_R), ri = r % TILE_R;
62	  const co = Math.floor(c / TILE_C), ci = c % TILE_C;
63	  return ro * (TILE_SZ * N_TILE_C) + ri * TILE_C + co * TILE_SZ + ci;
64	}
65	
66	function invTiled(addr) {
67	  const ro = Math.floor(addr / (TILE_SZ * N_TILE_C));
68	  const rem1 = addr % (TILE_SZ * N_TILE_C);
69	  const co = Math.floor(rem1 / TILE_SZ);
70	  const rem2 = rem1 % TILE_SZ;
71	  const ri = Math.floor(rem2 / TILE_C);
72	  const ci = rem2 % TILE_C;
73	  return { r: ro * TILE_R + ri, c: co * TILE_C + ci };
74	}
75	
76	function mk(t, c) { const d = document.createElement(t); if (c) d.className = c; return d; }
77	
78	let hovCell = null;
79	let drawing = false;
80	
81	function draw() {
82	  drawing = true;
83	  drawLogicalGrid();
84	  drawPhysicalMemoryGrid();
85	  drawStrips();
86	  drawFormula();
87	  drawArrow();
88	  setTimeout(() => { drawing = false; }, 0);
89	}
90	
91	function drawLogicalGrid() {
92	  const g = document.getElementById('g0');
93	  g.innerHTML = '';
94	  g.style.gridTemplateColumns = '24px repeat(' + N + ',1fr)';
95	
96	  g.appendChild(mk('div', 'hdr'));
97	  for (let c = 0; c < N; c++) {
98	    const h = mk('div', 'hdr'); h.textContent = 'c' + c; g.appendChild(h);
99	  }
100	
101	  const hovTile = hovCell ? tileId(hovCell.r, hovCell.c) : null;
102	
103	  for (let r = 0; r < N; r++) {
104	    const rl = mk('div', 'rl'); rl.textContent = 'r' + r; g.appendChild(rl);
105	    for (let c = 0; c < N; c++) {
106	      const d = mk('div', 'cell');
107	      d.dataset.r = r;
108	      d.dataset.c = c;
109	      d.textContent = r * N + c;
110	      d.style.background = '#f0f1f3';
111	      d.style.color = '#333';
112	      if (hovCell) {
113	        if (tileId(r, c) === hovTile) {
114	          d.classList.add('tile-hi');
115	        } else {
116	          d.classList.add('dm');
117	        }
118	      }
119	      if (hovCell && r === hovCell.r && c === hovCell.c) d.classList.add('hov');
120	      g.appendChild(d);
121	    }
122	  }
123	}
124	
125	function drawPhysicalMemoryGrid() {
126	  const g = document.getElementById('g1');
127	  g.innerHTML = '';
128	  g.style.gridTemplateColumns = '36px repeat(' + N + ',1fr)';
129	
130	  g.appendChild(mk('div', 'hdr'));
131	  for (let c = 0; c < N; c++) {
132	    const h = mk('div', 'hdr'); h.textContent = '+' + c; g.appendChild(h);
133	  }
134	
135	  const hovTile = hovCell ? tileId(hovCell.r, hovCell.c) : null;
136	
137	  for (let mr = 0; mr < N; mr++) {
138	    const rl = mk('div', 'rl'); rl.textContent = (mr * N); g.appendChild(rl);
139	    for (let mc = 0; mc < N; mc++) {
140	      const physAddr = mr * N + mc;
141	      const logical = invTiled(physAddr);
142	      const logVal = logical.r * N + logical.c;
143	
144	      const d = mk('div', 'cell');
145	      d.dataset.r = logical.r;
146	      d.dataset.c = logical.c;
147	      d.textContent = logVal;
148	      d.style.background = '#f0f1f3';
149	      d.style.color = '#333';
150	      if (hovCell) {
151	        if (tileId(logical.r, logical.c) === hovTile) {
152	          d.classList.add('tile-hi');
153	        } else {
154	          d.classList.add('dm');
155	        }
156	      }
157	      if (hovCell && logical.r === hovCell.r && logical.c === hovCell.c) d.classList.add('hov');
158	      g.appendChild(d);
159	    }
160	  }
161	}
162	
163	function drawStrips() {
164	  const ms0 = document.getElementById('m0');
165	  ms0.innerHTML = '';
166	  const hovFlatAddr = hovCell ? addrFlat(hovCell.r, hovCell.c) : null;
167	  const hovTileS = hovCell ? tileId(hovCell.r, hovCell.c) : null;
168	  for (let a = 0; a < TOTAL; a++) {
169	    const d = mk('div', 'ms');
170	    const rr = Math.floor(a / N), cc = a % N;
171	    if (hovCell && tileId(rr, cc) === hovTileS) {
172	      d.style.background = '#dbeafe';
173	      d.style.color = '#1e40af';
174	    } else if (hovCell) {
175	      d.style.opacity = '0.25';
176	    }
177	    if (hovFlatAddr !== null && a === hovFlatAddr) {
178	      d.classList.add('hov-hit');
179	      d.textContent = a;
180	    }
181	    ms0.appendChild(d);
182	  }
183	
184	  const ms1 = document.getElementById('m1');
185	  ms1.innerHTML = '';
186	  const hovTiledAddr = hovCell ? addrTiled(hovCell.r, hovCell.c) : null;
187	  const hovTileS1 = hovCell ? tileId(hovCell.r, hovCell.c) : null;
188	  for (let a = 0; a < TOTAL; a++) {
189	    const d = mk('div', 'ms');
190	    const tl = invTiled(a);
191	    if (hovCell && tileId(tl.r, tl.c) === hovTileS1) {
192	      d.style.background = '#dbeafe';
193	      d.style.color = '#1e40af';
194	    } else if (hovCell) {
195	      d.style.opacity = '0.25';
196	    }
197	    if (hovTiledAddr !== null && a === hovTiledAddr) {
198	      d.classList.add('hov-hit');
199	      d.textContent = a;
200	    }
201	    ms1.appendChild(d);
202	  }
203	}
204	
205	function drawFormula() {
206	  const fb = document.getElementById('fb');
207	  if (!hovCell) {
208	    fb.innerHTML = '<div class="ftitle">Click a cell to see how logical element maps to physical memory</div>';
209	    return;
210	  }
211	  const {r, c} = hovCell;
212	  const logVal = r * N + c;
213	  const at = addrTiled(r, c);
214	  const ro = Math.floor(r / TILE_R), ri = r % TILE_R;
215	  const co = Math.floor(c / TILE_C), ci = c % TILE_C;
216	  let html = `<div class="ftitle">Element ${logVal} at (row=${r}, col=${c})</div>`;
217	  html += '<div class="fcontent">';
218	  html += `coord = (row // 2, row % 2, col // 4, col % 4) = (${ro}, ${ri}, ${co}, ${ci})<br>`;
219	  html += `addr = (row // 2) × 16 + (row % 2) × 4 + (col // 4) × 8 + (col % 4)<br>`;
220	  html += `&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;= (${r} // 2) × 16 + (${r} % 2) × 4 + (${c} // 4) × 8 + (${c} % 4)<br>`;
221	  html += `&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;= ${ro} × 16 + ${ri} × 4 + ${co} × 8 + ${ci} = <b>${at}</b>`;
222	  html += '</div>';
223	  fb.innerHTML = html;
224	}
225	
226	// Arrow overlay
227	const panels = document.getElementById('panels');
228	const arrowSvg = document.getElementById('arrow');
229	
230	function drawArrow() {
231	  arrowSvg.innerHTML = '';
232	  const hovs = panels.querySelectorAll('.cell.hov');
233	  if (hovs.length < 2) return;
234	  const pr = panels.getBoundingClientRect();
235	  const a = hovs[0].getBoundingClientRect(), b = hovs[1].getBoundingClientRect();
236	  const x1 = a.left + a.width/2 - pr.left, y1 = a.top - pr.top;
237	  const x2 = b.left + b.width/2 - pr.left, y2 = b.top - pr.top;
238	  const mx = (x1 + x2) / 2, my = -10;
239	  const d = `M${x1},${y1} Q${mx},${my} ${x2},${y2}`;
240	  const ns = 'http://www.w3.org/2000/svg';
241	  const defs = document.createElementNS(ns, 'defs');
242	  const marker = document.createElementNS(ns, 'marker');
243	  marker.setAttribute('id', 'ah'); marker.setAttribute('markerWidth', '8'); marker.setAttribute('markerHeight', '6');
244	  marker.setAttribute('refX', '7'); marker.setAttribute('refY', '3'); marker.setAttribute('orient', 'auto');
245	  const poly = document.createElementNS(ns, 'polygon');
246	  poly.setAttribute('points', '0 0, 8 3, 0 6'); poly.setAttribute('fill', '#222');
247	  marker.appendChild(poly); defs.appendChild(marker); arrowSvg.appendChild(defs);
248	  const path = document.createElementNS(ns, 'path');
249	  path.setAttribute('d', d); path.setAttribute('marker-end', 'url(#ah)');
250	  arrowSvg.appendChild(path);
251	}
